import{_ as e,o,c as t,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Ceph Month 2021: The go-ceph get together BoF","description":"","frontmatter":{"title":"Ceph Month 2021: The go-ceph get together BoF","date":"2021-06-10T00:00:00.000Z","updated":"2021-06-11T00:00:00.000Z","tags":["Ceph","GoCeph","分布式存储","CephFS","RBD"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Month_2021_-_The_go-ceph_get_together_BoF.md","filePath":"posts/2021/Ceph_Month_2021_-_The_go-ceph_get_together_BoF.md","lastUpdated":1780459816000}'),a={name:"posts/2021/Ceph_Month_2021_-_The_go-ceph_get_together_BoF.md"};function h(r,l,n,p,s,_){return o(),t("div",null,[...l[0]||(l[0]=[i('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议基本信息" tabindex="-1">会议基本信息 <a class="header-anchor" href="#会议基本信息" aria-label="Permalink to &quot;会议基本信息&quot;">​</a></h4><ul><li><strong>主持人</strong>: John Mulligan</li><li><strong>主题</strong>: GoCeph项目公开讨论</li><li><strong>时间</strong>: 具体时间未提及</li></ul><h4 id="会议内容总结" tabindex="-1">会议内容总结 <a class="header-anchor" href="#会议内容总结" aria-label="Permalink to &quot;会议内容总结&quot;">​</a></h4><ol><li><p><strong>项目历史回顾</strong></p><ul><li>GoCeph项目始于2014年，由Noah Watkins发起，John Mulligan和其他维护者于2019年加入。</li><li>项目自2020年2月发布第一个官方版本0.2以来，每两个月发布一次新版本。</li><li>主要模块包括FFS、RADOS和RBD，提供Ceph API的Go语言封装。</li></ul></li><li><p><strong>项目现状</strong></p><ul><li>主要目标是提供与Go函数类似的Ceph API，简化C语言的复杂性。</li><li>RBD API是重点开发领域，CSI项目是其主要用户。</li><li>近期更新包括RBD镜像、快照以及厚/薄图像配置。</li></ul></li><li><p><strong>未来计划</strong></p><ul><li>完成RBD镜像和CephFS镜像功能。</li><li>评估并封装更多Ceph API。</li><li>提高性能增强，如共享缓冲区。</li></ul></li><li><p><strong>技术发展</strong></p><ul><li>开发了多个管理包，如CephAdmin、RBDAdmin和RGWAdmin，使用JSON API进行管理操作。</li><li>研究Go和C之间共享缓冲区的性能增强。</li></ul></li><li><p><strong>社区和文档</strong></p><ul><li>需要提高PR处理速度和改进文档。</li><li>正在考虑从v0升级到v1，但需要确保API的兼容性。</li></ul></li><li><p><strong>用户和项目反馈</strong></p><ul><li>讨论了如何更好地了解用户需求和优先级。</li><li>提到了一些使用GoCeph的项目，如CSI驱动和Rook。</li></ul></li><li><p><strong>技术细节讨论</strong></p><ul><li>讨论了Admin Socket的实现和GoCeph在Mac上的兼容性。</li><li>提到了改进PR处理速度和自动化测试的可能性。</li></ul></li></ol><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>继续开发RBD镜像和CephFS镜像功能。</li><li>评估并决定哪些Ceph API需要优先封装。</li><li>改进文档和错误处理，准备从v0升级到v1。</li><li>探索提高PR处理速度的方法，如减少审查要求或增加自动化测试。</li></ul><h4 id="会议结束" tabindex="-1">会议结束 <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束&quot;">​</a></h4><ul><li>会议在讨论了未来可能的改进和用户反馈后结束。</li><li>会议记录将被上传到Ceph YouTube频道。</li></ul><p><strong>备注</strong>: 会议中提到的具体技术细节和项目名称（如CSI、Rook、Admin Socket等）是Ceph和GoCeph项目中的关键术语，保留原文有助于理解相关领域的专业内容。</p>',10)])])}const d=e(a,[["render",h]]);export{u as __pageData,d as default};
